/**
 * French message catalog. Must carry exactly the same keys as `en.ts` —
 * `Record<MessageKey, string>` below makes a missing/extra key a real
 * TypeScript error, not a silent runtime fallback discovered later.
 *
 * Domain-register note (see todo-i18n.md decision 5): general chrome
 * uses everyday French; pharma/regulatory terms use the standard French
 * pharmacovigilance/quality vocabulary where one exists (e.g.
 * "pharmacovigilance," "dossier," "écart" for deviation,
 * "non-conformité," "action corrective/préventive" for CAPA). Terms
 * flagged inline with a comment are the ones most likely to need a
 * native reviewer's correction later — not blocking, per decision 5.
 */
