  'pvCaseDetail.infoRegSubmission':
    'Ceci génère le véritable rapport électronique attendu par le régulateur (XML E2B) ainsi qu\'une version PDF lisible pour vos propres dossiers — cela ne soumet rien automatiquement. Une fois le XML téléversé vous-même sur le portail de l\'autorité (p. ex. VigiFlow/PvERS), revenez joindre la preuve de ce téléversement ci-dessous — le cas ne peut passer à « Soumis » avant que cela soit joint.',
  'pvCaseDetail.capturedVia': "Capturé via {channel}, sans déclarant connecté — aucun membre du personnel n'a créé ce cas directement.",
