  'pvCaseDetail.weeksValue': '{weeks} semaines',
  'pvCaseDetail.followUpDue': 'Suivi dû le {date}',
  'pvCaseDetail.sectionCausalityAssessments': 'Évaluations de causalité ({n})',
  'pvCaseDetail.infoCausalityWhatThisIs': "Ce que c'est :",
  'pvCaseDetail.infoCausalityBody1': 'pour chaque produit suspecté associé à chaque réaction rapportée, quelqu’un doit juger',
  'pvCaseDetail.infoCausalityBodyEm': 'la probabilité que ce médicament précis ait causé cette réaction précise',
  'pvCaseDetail.infoCausalityBody2':
    "— pas seulement par cas, mais par paire, car un cas avec 2 médicaments et 2 réactions nécessite 4 jugements distincts (le médicament A peut clairement expliquer l'éruption cutanée tout en étant sans rapport avec les nausées, par exemple). Deux véritables méthodes de notation de pharmacovigilance produisent ce jugement, saisies indépendamment :",
  'pvCaseDetail.whoUmcLabel': 'OMS-UMC',
  'pvCaseDetail.infoCausalityWhoUmc':
    '(choisir l’une des 6 catégories — Certaine, Probable, Possible, Improbable, etc. — guidée par une liste de vérification de ce qui doit être vrai pour chacune)',
  'pvCaseDetail.andWord': 'et',
  'pvCaseDetail.naranjoLabel': 'Naranjo',
  'pvCaseDetail.infoCausalityNaranjo':
    "(10 questions oui/non/je ne sais pas, totalisées automatiquement en un score d'environ -4 à +13, interprété comme Définitive/Probable/Possible/Douteuse). Cliquez sur une paire ci-dessous pour ouvrir son évaluation.",
  'pvCaseDetail.sectionConsent': 'Consentement',
  'pvCaseDetail.infoConsentWhatThisMeans': 'Ce que cela signifie ici :',
  'pvCaseDetail.infoConsentBody1': 'pas le consentement au traitement — le consentement à',
  'pvCaseDetail.infoConsentBodyEm': 'traiter et signaler',
  'pvCaseDetail.infoConsentBody2':
    "ces informations sur l'effet indésirable, y compris leur partage avec le régulateur (PPB) si nécessaire. Un rapport de cas contient souvent des informations de santé identifiables, donc avant qu'il ne soit utilisé et transmis, il doit exister une trace de la demande et de la réponse obtenue du patient (ou de la personne ayant signalé en son nom). Il s'agit d'une trace de conformité/d'audit, non d'une exigence clinique — le cas existe toujours et peut être traité quelle que soit la réponse ; cela ne fait que suivre si la permission a été demandée et quelle a été la réponse.",
  'pvCaseDetail.reportConsentLabel': 'Consentement au signalement',
  'pvCaseDetail.sectionCaseFollowUp': 'Suivi du cas',
  'pvCaseDetail.subtitleCaseFollowUp':
    'Recontacter le déclarant pour des détails manquants ou une mise à jour de l’évolution — jusqu’à deux tentatives, clôture sous 28 jours',
  'pvCaseDetail.infoFollowUp':
    'Le suivi nécessite le consentement du déclarant à être contacté (un consentement « contact » distinct du consentement au signalement ci-dessus) avant l’envoi d’un e-mail automatique — sans cela, le système ouvre la même fenêtre de tentative suivie, mais s’appuie sur un appel humain au déclarant et la saisie du résultat. La tentative 1 dispose de 5 jours ouvrés pour obtenir une réponse ; une absence de réponse déclenche la tentative 2 aux mêmes conditions ; toujours rien clôture le cas comme échec de suivi. Toute réponse réelle réinitialise le délai à 7 jours. Le cycle complet se clôture sous 28 jours à partir du démarrage, quoi qu’il arrive.',
  'pvCaseDetail.sectionSourceDocuments': 'Documents source',
  'pvCaseDetail.subtitleSourceDocuments': "Le ou les documents originaux obligatoires à partir desquels ce cas a été capturé",
  'pvCaseDetail.noSourceDocLinked': 'Aucun document source lié pour l’instant.',
