  // Quality Waste Disposal (QualCloud Phase 1 Pass B, item B)
  'wasteDisposal.step2Title': 'Déposer la demande auprès du PPB et payer les frais',
  'wasteDisposal.step2Why': "Déposez une demande auprès du Pharmacy and Poisons Board sur le formulaire du Second Schedule Part A et payez les frais de 2 500 KES (Second Schedule Part B ; r.17(2)). Le PPB doit émettre le certificat d'élimination sûre dans les 30 jours de la demande (r.17(3)).",
  'wasteDisposal.step3Title': "Joindre la facture et la preuve de paiement",
  'wasteDisposal.step3Why': "Conservez la facture des frais et le reçu de paiement sur le dossier. Les deux sont requis avant que le dossier puisse être clôturé.",
  'wasteDisposal.step4Title': 'Remettre à une entreprise d\'élimination agréée',
  'wasteDisposal.step4Why': "Les déchets ne peuvent être remis qu'à une personne autorisée à les éliminer dans une installation approuvée (r.11(3)). Enregistrez l'entreprise, joignez son certificat, et marquez le certificat comme vérifié par le PPB.",
  'wasteDisposal.step5Title': 'Destruction sous supervision',
  'wasteDisposal.step5Why': "L'élimination est supervisée par le Board sur un site approuvé par la NEMA (r.17(1)). Le processus client exige également la présence d'un représentant du client et d'un agent du PPB. Téléchargez les photos de destruction ; elles sont combinées en un seul PDF.",
  'wasteDisposal.step6Title': "Joindre le certificat d'élimination sûre du PPB",
